/* ============================================================
   assets/textures.js - zemin dokulari (512x512 JPEG, base64)

   gfx.js bunu <script> ile yukler: file:// uzerinde WebGL resim
   dosyasini doku yapamaz ama data: URL ve script calisir.
   Hepsi CC0 (kamu mali) - kaynaklar:
     grass     ambientCG "Grass004"  - CC0 1.0 - https://ambientcg.com/view?id=Grass004
     meadow    ambientCG "Ground037" - CC0 1.0 - https://ambientcg.com/view?id=Ground037
     dirt      Poly Haven "dry_ground_rocks" (Rob Tuytel) - CC0 - https://polyhaven.com/a/dry_ground_rocks
     rock      Poly Haven "rock_boulder_dry" (D. Savva, R. Cilliers) - CC0 - https://polyhaven.com/a/rock_boulder_dry
     sand      Poly Haven "sand_01" (Rob Tuytel) - CC0 - https://polyhaven.com/a/sand_01
     cracked   Poly Haven "mud_cracked_dry_03" (D. Barresi, D. Savva) - CC0 - https://polyhaven.com/a/mud_cracked_dry_03
     cliff     Poly Haven "rock_face_03" (D. Barresi, R. Cilliers) - CC0 - https://polyhaven.com/a/rock_face_03
     mossrock  Poly Haven "aerial_rocks_02" (Rob Tuytel) - CC0 - https://polyhaven.com/a/aerial_rocks_02
     ripples   Poly Haven "aerial_beach_01" (Rob Tuytel) - CC0 - https://polyhaven.com/a/aerial_beach_01
   Uretim: 1K diffuse -> 512 LANCZOS -> JPEG q85.
   ============================================================ */
window.EV = window.EV || {};
EV.TEXDATA = {
  grass: 'data:image/jpeg;base64,',
  meadow: 'data:image/jpeg;base64,',
  dirt: 'data:image/jpeg;base64,',
  rock: 'data:image/jpeg;base64,',
  sand: 'data:image/jpeg;base64,',
  cracked: 'data:image/jpeg;base64,',
  cliff: 'data:image/jpeg;base64,',
  mossrock: 'data:image/jpeg;base64,',
  ripples: 'data:image/jpeg;base64,',
};
if (EV.GFX && EV.GFX.texturesArrived) EV.GFX.texturesArrived();
